import json

# Look for all submission actions in the sessions log
session_path = "/home/USER/runs/paper/qwen-hpl0-u1-turns/frozen/held-out-reference/play/users/u027/system/state/sessions/01a19345-c3e3-709a-9e13-f933d97bd53f.jsonl"

task_id = "task-8d27c4e9"

actions_by_submission = {}
for line in open(session_path):
    entry = json.loads(line)
    messages = entry.get('messages', [])
    for msg in messages:
        if msg.get('role') == 'assistant':
            content = msg.get('content', '')
            if 'action' in content.lower() and task_id in content:
                # Extract action
                if '"action"' in content:
                    # Search this content for submit action
                    import re
                    match = re.search(r'"action":\s*"(\w+)"', content)
                    if match:
                        action = match.group(1)
                        submission_num = actions_by_submission.get(action, {}).get('num', 0) + 1
                        if action not in actions_by_submission:
                            actions_by_submission[action] = {'num': submission_num, 'count': [0] * 4}
                        actions_by_submission[action]['num'] = submission_num
                        actions_by_submission[action]['count'][submission_num % 4] = content[:200]
                        print(f"Found action '{action}' (attempt {submission_num if submission_num <= 4 else '++'})")
                        if submission_num == 1:
                            print(f"  First '{action}' attempt found")
                        elif submission_num == 2:
                            print(f"  Second '{action}' attempt found")

print("\nSummary by action name:")
for action, data in sorted(actions_by_submission.items()):
